  &reftitle.examples;


    Cria uma imagem gradiente usando Imagick::sigmoidalContrastImage,
    adequada para mesclar duas imagens suavemente, com a mesclagem definida por
    alpha e beta



<?php

function generateBlendImage($width, $height, $alpha = 10, $beta = 0.5)
{
    $imagick = new Imagick();
    $imagick->newPseudoImage($width, $height, 'gradient:black-white');
    $quanta = $imagick->getQuantumRange();
    $imagick->sigmoidalContrastImage(true, $alpha, $beta * $quanta["quantumRangeLong"]);

    return $imagick;
}
